    ::setValue(market, std::string("type"), std::string("spot"));
    //
    // ########### test different variations ###########
    //
    // case #1, should prevail: param
    //
    std::any marketType1params1Variable = exchange.handleMarketTypeAndParams(std::string("fetchX"), market, initialParams, std::string("valueDefault"));
    std::any marketType1 = ::getValue(marketType1params1Variable, 0);
